Matching Ayahs
- = Alif, Lam, Mim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Disse er på rette vej fra deres Herre, og det er dem, der har succes. 2:5; 31:5
- = I Israels børn, husk Min nåde, som Jeg viste jer, og at Jeg foretrak jer frem for alle folk. 2:47; 2:122
- = Det var et folk, der er svundet ind. De får, hvad de har fortjent, og I får, hvad I har fortjent. Og I vil ikke blive spurgt om, hvad de plejede at gøre. 2:134; 2:141
- = De skal være der for evigt; straffen vil ikke blive lettet for dem, og de vil ikke få udsættelse. 2:162; 3:88
- = Bortset fra dem, der omvender sig efter dette og retter sig. For Allah er tilgivende, barmhjertig. 3:89; 24:5
- = Men de, der ikke tror og fornægter Vores tegn – de er helvedes folk. 5:10; 5:86
- = Og intet tegn kommer til dem fra deres Herres tegn, uden at de vender sig bort fra det. 6:4; 36:46
- = Og sendebud blev gjort til grin før dig, men dem, der gjorde grin med dem, blev omringet af det, de plejede at gøre grin med. 6:10; 21:41
- = Sig: "Jeg frygter, hvis jeg er ulydig mod min Herre, straffen på en stor dag." 6:15; 39:13
- = Så greb jordskælvet dem, og de forblev i deres hjem liggende på knæ. 7:78; 7:91
- = Så kastede han sin stav, og se, den var en tydelig slange. 7:107; 26:32
- = Og han trak sin hånd ud, og se, den var hvid (strålende) for tilskuerne. 7:108; 26:33
- = De sagde: "Vi tror på verdenernes Herre." 7:121; 26:47
- = Moses' og Haruns Herre. 7:122; 26:48
- = Og Jeg vil give dem tid. For min plan er stærk. 7:183; 68:45
- = Det er Ham, der sendte Sin Sendebud med vejledning og sandhedens religion for at lade den sejre over al religion, selv om polyteisterne hader det. 9:33; 61:9
- = O profet, kæmp mod de vantro og hyklerne og vær hård mod dem. Deres tilflugt er helvede, og en elendig skæbne! 9:73; 66:9
- = Og de siger: "Hvornår er dette løfte, hvis I taler sandt?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Og Vi sendte Moses med Vores tegn og en klar myndighed. 11:96; 40:23
- = Og Vi gav Moses skriften, men der blev uenighed om den. Og hvis det ikke var for et ord, der var gået forud fra din Herre, ville der være blevet dømt mellem dem. Og de er i tvivl om den. 11:110; 41:45
- = Det er ikke vanskeligt for Allah. 14:20; 35:17
- = Og når Jeg har formet ham og åndet af Min ånd i ham, så fald ned og bøj jer for ham." 15:29; 38:72
- = Så englene bøjede sig – alle sammen. 15:30; 38:73
- = (Allah) sagde: "Så gå ud af det, for du er forvist." 15:34; 38:77
